package com.lbos.commercecustomer.service.impl; import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.exception.*;import com.lbos.commercecustomer.mapper.CommerceMapper;import com.lbos.commercecustomer.repository.*;import com.lbos.commercecustomer.service.CustomerService;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*; @Service public class CustomerServiceImpl implements CustomerService {private final CustomerProfileRepository repo;private final CommerceMapper map;private final ContextSupport ctx;public CustomerServiceImpl(CustomerProfileRepository r,CommerceMapper m,ContextSupport c){repo=r;map=m;ctx=c;}@Transactional public CustomerResponse create(CreateCustomerRequest r){var userAccountId=ctx.currentUserAccountId();if(repo.existsByUserAccountId(userAccountId))throw new DuplicateResourceException("Customer profile already exists");var profile=new CustomerProfile();profile.setUserAccountId(userAccountId);profile.setDateOfBirth(r.dateOfBirth());return map.customer(repo.save(profile));}@Transactional(readOnly=true) public CustomerResponse me(){return map.customer(ctx.customer());}@Transactional(readOnly=true) public PageResponse<CustomerResponse> search(String s,int p,int z){var profilePage=repo.findAll(PageRequest.of(p,z));return new PageResponse<>(profilePage.map(map::customer).getContent(),p,z,profilePage.getTotalElements(),profilePage.getTotalPages());}@Transactional public CustomerResponse update(UpdateCustomerRequest r){var profile=ctx.customer();profile.setDateOfBirth(r.dateOfBirth());return map.customer(repo.save(profile));}@Transactional public void deleteMe(){repo.delete(ctx.customer());}}